wolfssl_ctx_new（）で作成されたSSLコンテキストへのポインタ。 Example WOLFSSL_CTX*ctx=0;
//Receivecallbackprototype
intMyEmbedReceive(WOLFSSL*ssl,char*buf,intsz,void*ctx);
//RegisterthecustomreceivecallbackwithwolfSSL
wolfSSL_CTX_SetIORecv(ctx,MyEmbedReceive);
intMyEmbedReceive(WOLFSSL*ssl,char*buf,intsz,void*ctx)
{
//customEmbedReceivefunction
}

wolfssl_new（）で作成されたSSLセッションへのポインタ。 Example intsockfd;
WOLFSSL*ssl=0;
...
//ManuallysettingthesocketfdasthereceiveCTX,forexample
wolfSSL_SetIOReadCtx(ssl,&sockfd);
...

wolfssl_new（）で作成されたSSLセッションへのポインタ。 Example intsockfd;
WOLFSSL*ssl=0;
...
//ManuallysettingthesocketfdasthesendCTX,forexample
